using System;

namespace StdbModule;

public static partial class UkrainianQuotes
{
    public static class ЛесяУкраїнка
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Гетьте, думи, ви хмари осінні! То ж тепера весна золота!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Ні, я хочу крізь сльози сміятись, Серед лиха співати пісні,", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Без надії таки сподіватись, Жити хочу! Геть, думи сумні!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Боги в тім винні, що дали тобі пізнати правду, сили ж не дали, щоб керувати правдою.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "«Божая іскра» – то тяжке прокляття, дикий і лютий пожар.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Будь проклята кров ледача, не за рідний край пролита.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Врятуєш душу, коли загубиш тіло.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Всі – жінки, коли вони кохають.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Геройство мусить мати нагороду, се і Боги, і люди признають.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Гумор найкраще враження робить при серйозному тоні.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Для гордої і владної душі життя і воля – на горі високій.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Для згаслих душ і безкорінних рас Однаково ворожі – степ і море.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "І доки рідний край Єгиптом буде? Коли новий загине Вавилон?", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Завжди терновий вінець Буде кращий, ніж царська корона.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Завжди величніша путь На Голгофу, ніж хід тріумфальний.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Земля не пекло, люди не прокляті, і радощі не гріх, а Божий дар.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "З рук смерті люди дістають безсмертя.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Краса – змагання до досконалості.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Крила знов на волі виростають у соколів приборканих.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Коли хто вмів одважно йти на страту, Той мусить все одважно зустрічать.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Кров без любові викупить не може.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Кохання – як вода: плавке та бистре, рве, грає, пестить, затягає й топить.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Люди й покоління – се тільки кільця в ланцюгу великім всесвітнього життя, а той ланцюг порватися не може.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Малоросійство – це не політика і навіть не тактика, лише завжди апріорна і тотальна капітуляція.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Мене любов ненависті навчила.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Меча важкого рукоять Не важча від старої ліри.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Над всіх старшин найстарша правда.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "На ділі каймося, не на словах.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Не в ідеї сила, а в самій крові!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Не єдиним хлібом живе людина, але кожним словом, що з Божих уст виходить.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Немає честі нападати ззаду.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Не поет, хто забуває Про страшні народні рани,", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Щоб собі на вільні руки Золоті надіть кайдани!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Не поет, у кого думки не літають вільно в світі,", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "А заплутались навіки в золотії тонкі сіті...", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Не раз, хто забувається про завтра, той має вічність.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Одвага наша – меч, политий кров'ю.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Ось північ вдарила — найкращий праці час", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Пекло страшніше горить в нашім краю.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Такого раю я не розумію.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Права без обов’язків – то сваволя.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Ніхто не має більшої любові, Як той, що душу поклада за друзів.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Поетична мова – це найприродніша мова.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "При світлі волі всі краї хороші,", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Всі води гідні відбивати небо, Усі гаї подібні до Едему!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Слово, чому ти не твердая криця, Що серед бою так ясно іскриться?", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Чом ти не гострий, безжалісний меч, Той, що здійма вражі голови з плеч?", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Смерть – це велика всесвітня, космічна самота.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Смуток – не робота.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Солодка хвала від ворога на полі бою, та не в полоні!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Сором мовчки гинути й страждати, Як маєм у руках хоч заржавілий меч.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Сором – хилитися і долі коритися.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Стане вінцем лиш тоді плетениця тернова,коли вільна душею людина по волі квітчається терном.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Сум не має дна.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Слово, моя ти єдиная зброє!.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Терпіть кайдани – то всесвітський сором, забуть їх, не розбивши, – гірший стид.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Ти мене убити можеш, але жити не примусиш!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Тільки зрада шлюб християнський розлучити може. А справжній – тільки смерть.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "То не любов, що присяги боїться.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Тоненька смужка брехню від правди ділить у минулім, а в прийдешньому нема вже й смужки.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Трудно вірить, щоб погану одіж могла носить якась ідея гарна.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Ту брехню, що справдиться, всі правдою зовуть.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Усе відбивається в пісні, як в морі.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хай же промінь твоїх думок Поміж нами сяє, – «Огню іскра великого» Повік не згасає.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хіба крові не варта краса?", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто вам сказав, що я слабка, що я корюся долі?", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хіба тремтить моя рука, чи пісня й думка кволі?", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто визволиться сам, той буде вільний, Хто визволить кого, в неволю візьме.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто зрікся всього, а себе не зрікся, не любить той.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто любить, той уподобитись може до любого і тілом, і душею.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто на розпутті прожив все життя, не піде ні в рай, ані в пекло.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто не був високо, той зроду не збагне, як страшно впасти.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто не жив посеред бурі, той ціни не знає силі.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто нікчемну душу має, то така ж у нього мова.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Хто по неволі согрішив, той чистий.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Чесний покриву не потребує.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "…Щоб не плакать, я сміялась.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Що сльози там, де навіть крові мало!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Язви гоїть вогонь.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Як бридко ти промовив сі слова! Душа моя од їх перевернулась.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Мов з людських уст овечий голос чую.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Ізраїля нащадок так говорить!", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Не дивно, що з нащадками такими не може бути вже Єгова в спілці, як був з їх славним прадідом колись.", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Як може бути, щоб тіла ходили вкупі, Але душі двома шляхами й врозтіч?", Author = "Леся Українка" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "«Леся Українка, Ольга Кобилянська і Михайло Коцюбинський — се наш літературний аеропаґ, найвища інстанція.", Author = "Микола Євшан" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Вони на те, щоби література могла перебути час формування, не одну остру і небезпечну кризу талантів, вони реґулюють літературний дух і життя серед розбиття та зневіри, дають приклади монументальної сили, високих артистичних змагань та духової сили.", Author = "Микола Євшан" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Не всі, хто знають Лесю поетесу, письменницю, знають, яка то була ще й в інших багатьох відношеннях виключна, особлива, щедро обдарована природою людина.", Author = "Ізидора Косач" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Наприклад, Леся мала неабиякий хист до малювання і до музики. Та той хист, на жаль, їй не судилося розвинути через хворобу, що з нею боролася Леся роками.", Author = "Ізидора Косач" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Учитися малюванню змушена була покинути через недугу.", Author = "Ізидора Косач" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Музику Леся дуже любила і грала добре, та блискучої техніки ніколи не мала, бо техніка набувається вправами (віртуози-піаністи, як відомо, по декілька годин щоденно), а Леся фізично не могла часами просто сидіти, бо бували періоди, коли їй доводилося місяці лежати в гіпсі – в липких кайданах, як вона це називала.", Author = "Ізидора Косач" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Леся мала золоті руки, за висловленням однієї приятельки нашої мами.", Author = "Ізидора Косач" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Вона вміла як ніхто з нічого зробити щось дуже цікаве. Часто художнє.", Author = "Ізидора Косач" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Наприклад, з квітки маку, з сухої маківки, з папірців, з клаптиків шовкової матерії Леся робила для нас, молодших, чудові речі. Або могла з трісочок кори зробити лицаря в латах.", Author = "Ізидора Косач" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Справжня її сила, те, чим вона важлива європейській, світовій культурі, її інновація і революція, те, без чого історія жіночої літератури на планеті Земля не може бути по праву відчитана, — це її двадцять драм; двадцять одна насправді.", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "«Шекспір в спідниці». І це й відповідь на питання, як її пропагувати, як про неї розповідати іноземцям.", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Касандра Лесі Українки, як і всі її жіночі характери, позбавлена віктимності в старому патріархальному сенсі слова...", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "А Дон-Жуан, якого вона, силами своїх героїнь Анни і Долорес, деконструювала й похоронила за покоління до того, як його деконструювала і похоронила європейська традиція!", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "«Історію Мавки може тільки жінка написати» – абсолютно феміністична заява;", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "ніXто так далеко не йшов тоді в ствердженні повноправного жіночого голосу в літературі, в переписуванні всієї європейської міфології з жіночої точки зору – від «Іліади» починаючи і «Дон-Жуаном» закінчуючи.", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Мова Лариси Косач двадцятьлітньої і мова Лариси Косач сорокалітньої – це дві різні мови.", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "«Блакитна троянда», перша її п’єса і єдина, яку вона побачила на сцені, викликала шок у публіки саме тим, що українською герої розмовляли про спадковість, психічні хвороби, емансипацію жінок, Данте і Крафт-Ебінґа, а не про народ, соловейка і криниченьку.", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Звісно, перед Лесею Українкою були «батьки», покоління Пчілки й Старицького, які свідомо «кували» українську термінологію, абстрактну лексику, але я саме її назвала б піонеркою української «інтеліґентської» мови, бо таки в неї першої українська мова вже «вміє все».", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Відповідає потребам повноструктурного модерного суспільства.", Author = "Оксана Забужко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Її індивідуалізм — бурхливий протест проти кволості й дрімливості громадянства, проти його невільницького духу й пасивності.", Author = "Микола Зеров" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "А її самотність на верхівях, далеко «від пахощів облесливих долин», то самотність творця, що в горах повинен, як Заратустра, передумати всю свою мудрість, щоб у належний час понести її в долини, віддати людям.", Author = "Микола Зеров" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "А що у Лесі бували часом індивідуалістичні настрої, що її зброя оберталася проти громадянства, що вона ставала на прю з ним, — то це звичайне явище, коли «ватажок», поет чи мислитель переростає своє оточення, убоге, безсиле, не розвинене естетично, не піднесене культурно.", Author = "Микола Зеров" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Коли «провідники» бачать те, що має прийти, але повести маси за собою не можуть, бо в розвитку самих мас немає для того «відповідних передумов».", Author = "Микола Зеров" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "До прикладу згадаю, що у Мглині жив батько Лесі Українки, юрист і громадський діяч Петро Косач, у Стародубі похований генеральний підскарбій, автор «Літопису Самовидця» Роман Ракушка-Романовський, а в Почепі стоять руїни палацу українського гетьмана Кирила Розумовського.", Author = "Василь Чепурний" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Тебе пече Кахетії сльоза, Згорьованої і запраглої;", Author = "Василь Стус" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Вола до неба гордий Алаверді Посеред пусток, посеред руїн…", Author = "Василь Стус" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "О, скільки вас, осмутних Україн, Мов матерів, рокованих до смерті.", Author = "Василь Стус" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Та ти не сам, народе мій. В борні Подасть грузин тобі незрадну руку,", Author = "Василь Стус" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Коли ти гнівом вибухнеш, розпукою У клечені грозовим блиском дні.", Author = "Василь Стус" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "І під червоні прапори світання Підуть повстанці: - На царя! На прю!", Author = "Василь Стус" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Здобувши в битві голубу зорю Прийдешніх днів, прийдешнього єднання.", Author = "Василь Стус" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "І люди йшли, куди вела їх жінка, — до дивного небаченого краю.", Author = "Галина Турелик" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Леся_Українка", Text = "Питали люди: «Хто ж бо ти такая?» Вона відповідала: «Українка».", Author = "Галина Турелик" },
        };
    }
}